Dependabot.ejemplo:
version: 2
updates:
  - package-ecosystem: "github-actions"
    directory: "/"
    schedule: { interval: "weekly" }
  - package-ecosystem: "npm"
    directory: "/"
    schedule: { interval: "daily" }
    groups: { minor-and-patch: { update-types: ["minor", "patch"] } }

Environment separation.ejemplo:
# Política de confianza IAM OIDC restringida por entorno
"Condition": {
  "StringEquals": {
    "token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
    "token.actions.githubusercontent.com:sub": "repo:org/app:environment:production"
  }
}
